    if (ctx.mailHTML) contactRows.push("<p><b>" + t("Эл. почта") + "</b><br>" + ctx.mailHTML + "</p>");
    if (ctx.address) contactRows.push("<p><b>" + t("Адрес") + "</b><br>" + esc(ctx.address) + "</p>");
