    LU: { parcel: [35.71, "dpd"], courier: [26.03, "smartpost"] },
    LV: { parcel: [5.58, "dpd"], courier: [8.00, "smartpost"] },
    NL: { parcel: [29.76, "dpd"], courier: [25.51, "smartpost"] },
    PL: { parcel: [17.86, "dpd"], courier: [20.66, "smartpost"] },
