  function edStockFor(p, variant) {
    var rows = S.stockLevels || [];
    for (var i = 0; i < rows.length; i++) {
      if (rows[i].productId === p.id && (rows[i].variant || "") === (variant || "")) return rows[i];
    }
    return null;
  }
