  function edSalonPct() {
    return (S.pricingLoaded && S.pricingLoaded.proDiscountPct != null) ? S.pricingLoaded.proDiscountPct : 20;
  }
  function edSalonOf(price) { return Math.round(price * (1 - edSalonPct() / 100) * 100) / 100; }
