      if (!hidP || hidP.custom) return;
      var hidWant = shopHidden(hidP.id);   // pressed while hidden = show again
      var hidEntry = demoApply({ type: "set_hidden", id: hidP.id, value: !hidWant,
        name: hidP.brand + " — " + hidP.name });
